cggsnUmtsQosCacMaxThruPut = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 241, 1, 3, 4, 3, 1, 7), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 4294967295)).clone(0)).setMaxAccess("readcreate")
