if mibBuilder.loadTexts: cggsnUmtsQosCacMaxThruPut.setStatus('current')
if mibBuilder.loadTexts: cggsnUmtsQosCacMaxThruPut.setDescription("This object defines highest peak throughput class for \n        R97/98 QoS can be accepted in a particular APN. This is used \n        only for GTP v0 PDP or GTP v1 PDP containing R97/98 QoS. If \n        the requested Peak throughput class is higher than highest \n        number, the request will be either downgrade to the value set,\n        or rejected. If this object is not set, it will be mapped to \n        R99 maximum bit rate rules for determining R99 attributes from \n        R97/98 attributes that is defined in 23.107. The Maximum Bit \n        Rate parameter will be applied.\n\n        If the value is set to '0', then any throughput will be \n        accepted.")
cggsnUmtsQosCacMaxThruPutReject = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 241, 1, 3, 4, 3, 1, 8), TruthValue().clone('false')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: cggsnUmtsQosCacMaxThruPutReject.setStatus('current')
if mibBuilder.loadTexts: cggsnUmtsQosCacMaxThruPutReject.setDescription("This object is used for downgrading or PDP to be rejected\n         when cggsnUmtsQosCacMaxThruPut is set.\n\n         'true'  - Reject the exceeding max throughput traffic.\n         'false' - Downgrade to the max throughput value set in\n                   cggsnUmtsQosCacMaxThruPut\n         \n         This object can be set to 'true', only when \n         cggsnUmtsQosCacMaxThruPut is set to a non-zero value.")
cggsnUmtsQosCacMaxDelayClass = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 241, 1, 3, 4, 3, 1, 9), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(0, 1, 2, 3, 4))).clone(namedValues=NamedValues(("none", 0), ("delayClass1", 1), ("delayClass2", 2), ("delayClass3", 3), ("delayClass4", 4))).clone('none')).setMaxAccess("readcreate")
